325	    /// Also auto expands sequence of sequences into flat sequence
326	    pub fn sequence_recursive_for_each<'a>(&'a self, f: &mut impl FnMut(&'a Self)) {
327	        if let Some(sequence) = self.to_packed::<SequenceElem>() {
328	            for child in &sequence.children {
329	                child.sequence_recursive_for_each(f);
