536	    /// Whether the content has the specified field.
537	    #[func(since = "forever")]
538	    pub fn has(
539	        &self,
540	        /// The field to look for.
541	        field: Str,
542	    ) -> bool {
543	        if field.as_str() == "label" {
544	            return self.label().is_some();
545	        }
546	
547	        let Some(id) = self.elem().field_id(&field) else {
548	            return false;
549	        };
550	
551	        match self.0.handle().field(id) {
552	            Some(field) => field.has(),
553	            None => false,
554	        }
555	    }
