625	impl Repr for Content {
626	    fn repr(&self) -> EcoString {
627	        self.0.handle().repr().unwrap_or_else(|| {
628	            let fields = self
629	                .0
630	                .handle()
631	                .fields()
632	                .filter_map(|field| field.get().map(|v| (field.name, v.repr())))
633	                .map(|(name, value)| eco_format!("{name}: {value}"))
634	                .collect::<Vec<_>>();
635	            eco_format!(
636	                "{}{}",
637	                self.elem().name(),
638	                repr::pretty_array_like(&fields, false),
639	            )
640	        })
641	    }
642	}
