644	impl Add for Content {
645	    type Output = Self;
646	
647	    fn add(self, mut rhs: Self) -> Self::Output {
648	        let mut lhs = self;
649	        match (lhs.to_packed_mut::<SequenceElem>(), rhs.to_packed_mut::<SequenceElem>()) {
650	            (Some(seq_lhs), Some(rhs)) => {
651	                seq_lhs.children.extend(rhs.children.iter().cloned());
652	                lhs
653	            }
654	            (Some(seq_lhs), None) => {
655	                seq_lhs.children.push(rhs);
656	                lhs
657	            }
658	            (None, Some(rhs_seq)) => {
659	                rhs_seq.children.insert(0, lhs);
660	                rhs
661	            }
662	            (None, None) => Self::sequence([lhs, rhs]),
663	        }
664	    }
665	}
