19	pub struct RawContent {
20	    /// A type-erased pointer to an allocation containing two things:
21	    /// - A header that is the same for all elements
22	    /// - Element-specific `data` that holds the specific element
23	    ///
24	    /// This pointer is valid for both a `Header` and an `Inner<E>` where
25	    /// `E::ELEM == self.elem` and can be freely cast between both. This is
26	    /// possible because
27	    /// - `Inner<E>` is `repr(C)`
28	    /// - The first field of `Inner<E>` is `Header`
29	    /// - ISO/IEC 9899:TC2 C standard § 6.7.2.1 - 13 states that a pointer to a
30	    ///   structure "points to its initial member" with no padding at the start
31	    ptr: NonNull<Header>,
32	    /// Describes which kind of element this content holds. This is used for
33	    ///
34	    /// - Direct comparisons, e.g. `is::<HeadingElem>()`
35	    /// - Behavior: An `Element` is just a pointer to a `ContentVtable`
36	    ///   containing not just data, but also function pointers for various
37	    ///   element-specific operations that can be performed
38	    ///
39	    /// It is absolutely crucial that `elem == <E as NativeElement>::ELEM` for
40	    /// `Inner<E>` pointed to by `ptr`. Otherwise, things will go very wrong
