47	/// The allocated part of an element's representation.
48	///
49	/// This is `repr(C)` to ensure that a pointer to the whole structure may be
50	/// cast to a pointer to its first field.
51	#[repr(C)]
52	struct Inner<E> {
53	    /// It is crucial that this is the first field because we cast between
54	    /// pointers to `Inner<E>` and pointers to `Header`. See the documentation
55	    /// of `RawContent::ptr` for more details.
56	    header: Header,
57	    /// The element struct. E.g. `E = HeadingElem`.
