61	/// The header that is shared by all elements.
62	struct Header {
63	    /// The element's reference count. This works just like for `Arc`.
64	    /// Unfortunately, we have to reimplement reference counting because we
65	    /// have a custom fat pointer and `Arc` wouldn't know how to drop its
66	    /// contents. Something with `ManuallyDrop<Arc<_>>` might also work, but at
67	    /// that point we're not gaining much and with the way it's implemented now
68	    /// we can also skip the unnecessary weak reference count.
69	    refs: AtomicUsize,
70	    /// Metadata for the element.
71	    meta: Meta,
72	    /// A cell for memoizing the hash of just the `data` part of the content.
