90	impl RawContent {
91	    /// Creates raw content wrapping an element, with all metadata set to
92	    /// default (including a detached span).
93	    pub(super) fn new<E: NativeElement>(data: E) -> Self {
94	        Self::create(
95	            data,
96	            Meta {
97	                label: None,
98	                location: None,
99	                lifecycle: SmallBitSet::new(),
100	            },
101	            HashLock::new(),
102	            Span::detached(),
103	        )
104	    }
105	
106	    /// Creates and allocates raw content.
107	    fn create<E: NativeElement>(data: E, meta: Meta, hash: HashLock, span: Span) -> Self {
108	        let raw = Box::into_raw(Box::<Inner<E>>::new(Inner {
109	            header: Header { refs: AtomicUsize::new(1), meta, hash },
110	            data,
111	        }));
112	
113	        // Safety: `Box` always holds a non-null pointer. See also
114	        // `Box::into_non_null` (which is unstable).
115	        let non_null = unsafe { NonNull::new_unchecked(raw) };
116	
117	        // Safety: See `RawContent::ptr`.
118	        let ptr = non_null.cast::<Header>();
119	
120	        Self { ptr, elem: E::ELEM, span }
121	    }
122	
123	    /// Destroys raw content and deallocates.
124	    ///
125	    /// # Safety
126	    /// - The reference count must be zero.
127	    /// - The raw content must be of type `E`.
128	    pub(super) unsafe fn drop_impl<E: NativeElement>(&mut self) {
129	        debug_assert_eq!(self.header().refs.load(Ordering::Relaxed), 0);
130	
131	        // Safety:
132	        // - The caller guarantees that the content is of type `E`.
133	        // - Thus, `ptr` must have been created from `Box<Inner<E>>` (see
134	        //   `RawContent::ptr`).
135	        // - And to clean it up, we can just reproduce our box.
136	        unsafe {
137	            let ptr = self.ptr.cast::<Inner<E>>();
138	            drop(Box::<Inner<E>>::from_raw(ptr.as_ptr()));
139	        }
140	    }
141	
142	    /// Clones a packed element into new raw content.
143	    pub(super) fn clone_impl<E: NativeElement>(elem: &Packed<E>) -> Self {
144	        let raw = &elem.pack_ref().0;
145	        let header = raw.header();
146	        RawContent::create(
147	            elem.as_ref().clone(),
148	            header.meta.clone(),
149	            header.hash.clone(),
150	            raw.span,
151	        )
152	    }
153	
154	    /// Accesses the header part of the raw content.
155	    fn header(&self) -> &Header {
156	        // Safety: `self.ptr` is a valid pointer to a header structure.
157	        unsafe { self.ptr.as_ref() }
158	    }
159	
160	    /// Mutably accesses the header part of the raw content.
161	    fn header_mut(&mut self) -> &mut Header {
162	        self.make_unique();
163	
164	        // Safety:
165	        // - `self.ptr` is a valid pointer to a header structure.
166	        // - We have unique access to the backing allocation (just ensured).
167	        unsafe { self.ptr.as_mut() }
168	    }
169	
170	    /// Retrieves the contained element **without checking that the content is
171	    /// of the correct type.**
172	    ///
173	    /// # Safety
174	    /// This must be preceded by a check to [`is`](Self::is). The safe API for
175	    /// this is [`Content::to_packed`](super::Content::to_packed) and the
176	    /// [`Packed`] struct.
177	    pub(super) unsafe fn data<E: NativeElement>(&self) -> &E {
178	        debug_assert!(self.is::<E>());
179	
180	        // Safety:
181	        // - The caller guarantees that the content is of type `E`.
182	        // - `self.ptr` is a valid pointer to an `Inner<E>` (see
183	        //   `RawContent::ptr`).
184	        unsafe { &self.ptr.cast::<Inner<E>>().as_ref().data }
185	    }
186	
187	    /// Retrieves the contained element mutably **without checking that the
188	    /// content is of the correct type.**
189	    ///
190	    /// Ensures that the element's allocation is unique.
191	    ///
192	    /// # Safety
193	    /// This must be preceded by a check to [`is`](Self::is). The safe API for
194	    /// this is [`Content::to_packed_mut`](super::Content::to_packed_mut) and
195	    /// the [`Packed`] struct.
196	    pub(super) unsafe fn data_mut<E: NativeElement>(&mut self) -> &mut E {
197	        debug_assert!(self.is::<E>());
198	
199	        // Ensure that the memoized hash is reset because we may mutate the
200	        // element.
201	        self.header_mut().hash.reset();
202	
203	        // Safety:
204	        // - The caller guarantees that the content is of type `E`.
205	        // - `self.ptr` is a valid pointer to an `Inner<E>` (see
206	        //   `RawContent::ptr`).
207	        // - We have unique access to the backing allocation (due to header_mut).
208	        unsafe { &mut self.ptr.cast::<Inner<E>>().as_mut().data }
209	    }
210	
211	    /// Ensures that we have unique access to the backing allocation by cloning
212	    /// if the reference count exceeds 1. This is used before performing
213	    /// mutable operations, implementing a clone-on-write scheme.
214	    fn make_unique(&mut self) {
215	        if self.header().refs.load(Ordering::Relaxed) > 1 {
216	            *self = self.handle().clone();
217	        }
218	    }
