220	    /// Retrieves the element this content is for.
221	    pub(super) fn elem(&self) -> Element {
222	        self.elem
223	    }
224	
225	    /// Whether this content holds an element of type `E`.
226	    pub(super) fn is<E: NativeElement>(&self) -> bool {
227	        self.elem == E::ELEM
228	    }
229	
230	    /// Retrieves the content's span.
231	    pub(super) fn span(&self) -> Span {
232	        self.span
233	    }
234	
235	    /// Retrieves the content's span mutably.
236	    pub(super) fn span_mut(&mut self) -> &mut Span {
237	        &mut self.span
238	    }
239	
240	    /// Retrieves the content's metadata.
241	    pub(super) fn meta(&self) -> &Meta {
242	        &self.header().meta
243	    }
244	
245	    /// Retrieves the content's metadata mutably.
246	    pub(super) fn meta_mut(&mut self) -> &mut Meta {
247	        &mut self.header_mut().meta
248	    }
249	
250	    /// Casts into a trait object for a given trait if the packed element
251	    /// implements said trait.
252	    pub(super) fn with<C>(&self) -> Option<&C>
253	    where
254	        C: ?Sized + 'static,
255	    {
256	        // Safety: The vtable comes from the `Capable` implementation which
257	        // guarantees to return a matching vtable for `Packed<T>` and `C`. Since
258	        // any `Packed<T>` is repr(transparent) with `Content` and `RawContent`,
259	        // we can also use a `*const RawContent` pointer.
260	        let vtable = (self.elem.vtable().capability)(TypeId::of::<C>())?;
261	        let data = self as *const Self as *const ();
262	        Some(unsafe { &*fat::from_raw_parts(data, vtable.as_ptr()) })
263	    }
264	
265	    /// Casts into a mutable trait object for a given trait if the packed
266	    /// element implements said trait.
267	    pub(super) fn with_mut<C>(&mut self) -> Option<&mut C>
268	    where
269	        C: ?Sized + 'static,
270	    {
271	        // Safety: The vtable comes from the `Capable` implementation which
272	        // guarantees to return a matching vtable for `Packed<T>` and `C`. Since
273	        // any `Packed<T>` is repr(transparent) with `Content` and `RawContent`,
274	        // we can also use a `*const Content` pointer.
275	        //
276	        // The resulting trait object contains an `&mut Packed<T>`. We do _not_
277	        // need to ensure that we hold the only reference to the `Arc` here
278	        // because `Packed<T>`'s DerefMut impl will take care of that if mutable
279	        // access is required.
280	        let vtable = (self.elem.vtable().capability)(TypeId::of::<C>())?;
281	        let data = self as *mut Self as *mut ();
282	        Some(unsafe { &mut *fat::from_raw_parts_mut(data, vtable.as_ptr()) })
283	    }
284	}
285	
286	impl RawContent {
287	    /// Retrieves the element's vtable.
288	    pub(super) fn handle(&self) -> vtable::ContentHandle<&RawContent> {
289	        // Safety `self.elem.vtable()` is a matching vtable for `self`.
290	        unsafe { vtable::Handle::new(self, self.elem.vtable()) }
291	    }
292	
293	    /// Retrieves the element's vtable.
294	    pub(super) fn handle_mut(&mut self) -> vtable::ContentHandle<&mut RawContent> {
295	        // Safety `self.elem.vtable()` is a matching vtable for `self`.
296	        unsafe { vtable::Handle::new(self, self.elem.vtable()) }
297	    }
298	
299	    /// Retrieves the element's vtable.
300	    pub(super) fn handle_pair<'a, 'b>(
301	        &'a self,
302	        other: &'b RawContent,
303	    ) -> Option<vtable::ContentHandle<(&'a RawContent, &'b RawContent)>> {
304	        (self.elem == other.elem).then(|| {
305	            // Safety:
306	            // - `self.elem.vtable()` is a matching vtable for `self`.
307	            // - It's also matching for `other` because `self.elem == other.elem`.
308	            unsafe { vtable::Handle::new((self, other), self.elem.vtable()) }
309	        })
310	    }
311	}
312	
313	impl Debug for RawContent {
314	    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
315	        self.handle().debug(f)
316	    }
317	}
318	
319	impl Clone for RawContent {
320	    fn clone(&self) -> Self {
321	        // See Arc's clone impl for details about memory ordering.
322	        let prev = self.header().refs.fetch_add(1, Ordering::Relaxed);
323	
324	        // See Arc's clone impl details about guarding against incredibly
325	        // degenerate programs.
326	        if prev > isize::MAX as usize {
327	            ref_count_overflow(self.ptr, self.elem, self.span);
328	        }
329	
330	        Self { ptr: self.ptr, elem: self.elem, span: self.span }
331	    }
332	}
333	
334	impl Drop for RawContent {
335	    fn drop(&mut self) {
336	        // Drop our ref-count. If there was more than one content before
337	        // (including this one), we shouldn't deallocate. See Arc's drop impl
338	        // for details about memory ordering.
339	        if self.header().refs.fetch_sub(1, Ordering::Release) != 1 {
340	            return;
341	        }
342	
343	        // See Arc's drop impl for details.
344	        atomic::fence(Ordering::Acquire);
345	
346	        // Safety:
347	        // No other content references the backing allocation (just checked)
348	        unsafe {
349	            self.handle_mut().drop();
350	        }
351	    }
352	}
353	
354	impl PartialEq for RawContent {
355	    fn eq(&self, other: &Self) -> bool {
356	        let Some(handle) = self.handle_pair(other) else { return false };
357	        handle
358	            .eq()
359	            .unwrap_or_else(|| handle.fields().all(|handle| handle.eq()))
360	    }
361	}
362	
363	impl Hash for RawContent {
364	    fn hash<H: Hasher>(&self, state: &mut H) {
365	        self.elem.hash(state);
366	        let header = self.header();
367	        header.meta.hash(state);
368	        header.hash.get_or_insert_with(|| self.handle().hash()).hash(state);
369	        self.span.hash(state);
370	    }
371	}
372	
373	// Safety:
374	// - Works like `Arc`.
375	// - `NativeElement` implies `Send` and `Sync`, see below.
376	unsafe impl Sync for RawContent {}
377	unsafe impl Send for RawContent {}
378	
379	fn _ensure_send_sync<T: NativeElement>() {
380	    fn needs_send_sync<T: Send + Sync>() {}
381	    needs_send_sync::<T>();
382	}
383	
384	#[cold]
385	fn ref_count_overflow(ptr: NonNull<Header>, elem: Element, span: Span) -> ! {
386	    // Drop to decrement the ref count to counter the increment in `clone()`
387	    drop(RawContent { ptr, elem, span });
388	    panic!("reference count overflow");
389	}
390	
391	#[cfg(test)]
392	mod tests {
393	    use crate::foundations::{NativeElement, Repr, StyleChain, Value};
394	    use crate::introspection::Location;
395	    use crate::model::HeadingElem;
396	    use crate::text::TextElem;
397	
398	    #[test]
399	    fn test_miri() {
400	        let styles = StyleChain::default();
401	
402	        let mut first = HeadingElem::new(TextElem::packed("Hi!")).with_offset(2).pack();
403	        let hash1 = typst_utils::hash128(&first);
404	        first.set_location(Location::new(10));
405	        let _ = format!("{first:?}");
406	        let _ = first.repr();
407	
408	        assert!(first.is::<HeadingElem>());
409	        assert!(!first.is::<TextElem>());
410	        assert_eq!(first.to_packed::<TextElem>(), None);
411	        assert_eq!(first.location(), Some(Location::new(10)));
412	        assert_eq!(first.field_by_name("offset"), Ok(Value::Int(2)));
413	        assert!(!first.has("depth".into()));
414	
415	        let second = first.clone();
416	        first.materialize(styles);
417	
418	        let first_packed = first.to_packed::<HeadingElem>().unwrap();
419	        let second_packed = second.to_packed::<HeadingElem>().unwrap();
420	
421	        assert!(first.has("depth".into()));
422	        assert!(!second.has("depth".into()));
423	        assert!(first_packed.depth.is_set());
424	        assert!(!second_packed.depth.is_set());
425	        assert_ne!(first, second);
426	        assert_ne!(hash1, typst_utils::hash128(&first));
427	    }
428	}
